class MarkdownCommandGenerator:
    def generate(self, prompt: dict) -> str:
        """Return a Markdown representation for a prompt"""
        title = prompt.get("title", "")
        description = prompt.get("description", "")
        return f"# {title}\n\n{description}\n"

class TomlCommandGenerator:
    def generate(self, prompt: dict) -> str:
        """Return TOML manifest for an agent command"""
        name = prompt.get("name", "unnamed")
        return f'title = "{name}"\nscript = """{prompt.get("body","")}"""\n'
